const plural=(n,one,many)=>n+' '+(n===1?one:many);
// Who made the knockouts, once guns, shields, falls or blasts made some (combat state.downs): ' (fighters 2 · ship guns 30 · shields 3)'.
const DOWN_TEXT=[['fighter','fighters'],['ship','ship guns'],['gun','castle guns'],['shield','shields'],['fall','falls'],['blast','core blasts'],['meltdown','meltdowns']],DEFENSE_TEXT=[['ship','Ship guns'],['gun','Castle guns'],['shield','Shield']];
const downsText=d=>{const parts=d?DOWN_TEXT.filter(([k])=>d[k]>0).map(([k,label])=>label+' '+d[k]):[];return parts.length>1||parts.length&&!d.fighter?' ('+parts.join(' · ')+')':'';};

